source_materials.text:
locals {
  bedrock_model_arn     = "arn:aws:bedrock:${var.region}::foundation-model/${var.kb_model_id}"
}

#############################
# Knowledgebase Role
#############################
resource "aws_iam_role" "kb_role" {
  name = "kb_role_${var.cgid}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "bedrock.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.aws-account-id.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:aws:bedrock:${var.region}:${data.aws_caller_identity.aws-account-id.account_id}:knowledge-base/*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "kb_role_policy" {
  name = "kb_role_policy_${var.cgid}"
  role = aws_iam_role.kb_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "bedrock:InvokeModel"
        Effect   = "Allow"
        Resource = local.bedrock_model_arn
      },
      {
        Sid      = "S3ListBucketStatement"
        Action   = [
          "s3:ListBucket",
          "s3:GetObject"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.kb_s3_bucket.arn,
          "${aws_s3_bucket.kb_s3_bucket.arn}/*"
        ]
      },
      {
        Action   = "aoss:APIAccessAll"
        Effect   = "Allow"
        Resource = aws_opensearchserverless_collection.kb_oss_collection.arn
      }
    ]
  })
}

resource "time_sleep" "kb_role_policy_sleep" {
  create_duration = "20s"
  depends_on      = [aws_iam_role_policy.kb_role_policy]
}

#############################
# Knowledgebase
#############################
resource "aws_bedrockagent_knowledge_base" "kb" {
  name     = "kb-${var.cgid}"
  role_arn = aws_iam_role.kb_role.arn
  knowledge_base_configuration {
    vector_knowledge_base_configuration {
      embedding_model_arn = local.bedrock_model_arn
    }
    type = "VECTOR"
  }
  storage_configuration {
    type = "OPENSEARCH_SERVERLESS"
    opensearch_serverless_configuration {
      collection_arn    = aws_opensearchserverless_collection.kb_oss_collection.arn
      vector_index_name = opensearch_index.kb_oss_index.name
      field_mapping {
        vector_field   = "kb-vector"
        text_field     = "AMAZON_BEDROCK_TEXT_CHUNK"
        metadata_field = "AMAZON_BEDROCK_METADATA"
      }
    }
  }
  depends_on = [
    opensearch_index.kb_oss_index,
    time_sleep.kb_role_policy_sleep
  ]
}

resource "aws_bedrockagent_data_source" "kb_data_source" {
  knowledge_base_id = aws_bedrockagent_knowledge_base.kb.id
  name              = "kb-datasource-${var.cgid}"
  data_source_configuration {
    type = "S3"
    s3_configuration {
      bucket_arn = aws_s3_bucket.kb_s3_bucket.arn
    }
  }
  vector_ingestion_configuration {
    chunking_configuration {
      chunking_strategy = "FIXED_SIZE"
      fixed_size_chunking_configuration {
        max_tokens         = 512
        overlap_percentage = 20
      }
    }
  }
}

resource "terraform_data" "kb_ingestion" {
  depends_on = [ aws_bedrockagent_data_source.kb_data_source ]

  triggers_replace = {
    kb_id    = aws_bedrockagent_knowledge_base.kb.id
    kb_ds_id = aws_bedrockagent_data_source.kb_data_source.data_source_id
  }

  provisioner "local-exec" {
    when       = create
    on_failure = fail
    command    = "aws bedrock-agent start-ingestion-job --knowledge-base-id ${self.triggers_replace.kb_id} --data-source-id ${self.triggers_replace.kb_ds_id} --region ${var.region} --profile ${var.profile}"
  }
}

#############################
# Code Interpreter Role
#############################
resource "aws_iam_role" "code_interpreter_role" {
  name = "agentcore_code_interpreter_execution_role_${var.cgid}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "bedrock-agentcore.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "code_interpreter_role_policy" {
  role   = aws_iam_role.code_interpreter_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.kb_code_interpreter_bucket.arn,
          "${aws_s3_bucket.kb_code_interpreter_bucket.arn}/*"
        ]
      }
    ]
  })
}

#############################
# Agent Runtime Role
#############################
resource "aws_iam_role" "agent_runtime_role" {
  name = "agentcore_agent_runtime_role_${var.cgid}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "bedrock-agentcore.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "agent_runtime_role_policy" {
  role   = aws_iam_role.agent_runtime_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BedrockModelInvocation"
        Effect = "Allow"
        Action = [
          "bedrock:InvokeModel",
          "bedrock:InvokeModelWithResponseStream"
        ]
        "Resource": "*"
      },
      {
        Sid    = "CodeInterpreterAccess"
        Effect = "Allow"
        Action = [
          "bedrock-agentcore:InvokeCodeInterpreter",
          "bedrock-agentcore:StartCodeInterpreterSession",
          "bedrock-agentcore:StopCodeInterpreterSession"
        ]
        "Resource": "*"
      },
      {
        Sid    = "KnowledgeBaseAccess"
        Effect = "Allow"
        Action = [
          "bedrock:Retrieve",
          "bedrock:RetrieveAndGenerate"
        ]
        "Resource": aws_bedrockagent_knowledge_base.kb.arn
      }
    ]
  })
}


#############################
# Starting User
#############################
resource "aws_iam_user" "starting_user" {
  name = "sandy_${var.cgid}"
}

resource "aws_iam_access_key" "starting_user_key" {
  user = aws_iam_user.starting_user.name
}

# Iam enumeration is not part of the challenge. Might as well make it easy
resource "aws_iam_user_policy_attachment" "starting_user_iam_policy_attachment" {
  user       = aws_iam_user.starting_user.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_policy" "starting_user_bedrock_policy" {
  name = "agent_access_policy_${var.cgid}"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid    = "BedrockReadOnly"
        Effect = "Allow"
        Action = [
          "bedrock:Get*",
          "bedrock:List*",
          "bedrock-agentcore:Get*",
          "bedrock-agentcore:List*"
        ],
        Resource = "*"
      },
      {
        Sid    = "CodeInterpreterManagement"
        Effect = "Allow",
        Action = [
          "bedrock-agentcore:*CodeInterpreter*"
        ],
        Resource = "*"
      },
      {
        Sid    = "CodeInterpreterRoleManagement"
        Effect = "Allow",
        Action = [
          "iam:PassRole"
        ],
        Resource = "arn:aws:iam::${data.aws_caller_identity.aws-account-id.account_id}:role/agentcore_*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "starting_user_bedrock_policy_attachment" {
  user       = aws_iam_user.starting_user.name
  policy_arn = aws_iam_policy.starting_user_bedrock_policy.arn
}

resource "aws_opensearchserverless_access_policy" "kb_oss_collection_policy" {
  name = "oss-access-${var.cgid}"
  type = "data"
  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "index"
          Resource = [
            "index/kb-oss-collection-${var.cgid}/*"
          ]
          Permission = [
            "aoss:CreateIndex",
            "aoss:DeleteIndex",
            "aoss:DescribeIndex",
            "aoss:ReadDocument",
            "aoss:UpdateIndex",
            "aoss:WriteDocument"
          ]
        },
        {
          ResourceType = "collection"
          Resource = [
            "collection/kb-oss-collection-${var.cgid}"
          ]
          Permission = [
            "aoss:CreateCollectionItems",
            "aoss:DescribeCollectionItems",
            "aoss:UpdateCollectionItems"
          ]
        }
      ],
      Principal = [
        aws_iam_role.kb_role.arn,
        data.aws_caller_identity.aws-account-id.arn
      ]
    }
  ])
}

# OpenSearch collection data encryption policy
resource "aws_opensearchserverless_security_policy" "kb_oss_encryption_policy" {
  name = "oss-encryption-${var.cgid}"
  type = "encryption"
  policy = jsonencode({
    Rules = [
      {
        Resource = [
          "collection/kb-oss-collection-${var.cgid}"
        ]
        ResourceType = "collection"
      }
    ],
    AWSOwnedKey = true
  })
}

# OpenSearch collection network policy
resource "aws_opensearchserverless_security_policy" "kb_oss_network_policy" {
  name = "oss-network-${var.cgid}"
  type = "network"
  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "collection"
          Resource = [
            "collection/kb-oss-collection-${var.cgid}"
          ]
        },
        {
          ResourceType = "dashboard"
          Resource = [
            "collection/kb-oss-collection-${var.cgid}"
          ]
        }
      ]
      AllowFromPublic = true
    }
  ])
}

# OpenSearch resource
resource "aws_opensearchserverless_collection" "kb_oss_collection" {
  name = "kb-oss-collection-${var.cgid}"
  type = "VECTORSEARCH"
  depends_on = [
    aws_opensearchserverless_access_policy.kb_oss_collection_policy,
    aws_opensearchserverless_security_policy.kb_oss_encryption_policy,
    aws_opensearchserverless_security_policy.kb_oss_network_policy
  ]
}

# Creating the index *immediately* after the collection sometimes fails on permissions errors.
# The access policy needs a few seconds to get recognized.
resource "time_sleep" "kb_oss_collection_sleep" {
  create_duration = "20s"
  depends_on      = [aws_opensearchserverless_collection.kb_oss_collection]
}

provider "opensearch" {
  url         = aws_opensearchserverless_collection.kb_oss_collection.collection_endpoint
  healthcheck = false
  aws_profile = var.profile
}

# OpenSearch index creation
resource "opensearch_index" "kb_oss_index" {
  name                           = "kb-index-${var.cgid}"
  number_of_shards               = "2"
  number_of_replicas             = "0"
  index_knn                      = true
  index_knn_algo_param_ef_search = "512"
  mappings                       = <<-EOF
    {
      "properties": {
        "kb-vector": {
          "type": "knn_vector",
          "dimension": 1024,
          "method": {
            "name": "hnsw",
            "engine": "faiss",
            "parameters": {
              "m": 16,
              "ef_construction": 512
            },
            "space_type": "l2"
          }
        },
        "AMAZON_BEDROCK_METADATA": {
          "type": "text",
          "index": "false"
        },
        "AMAZON_BEDROCK_TEXT_CHUNK": {
          "type": "text",
          "index": "true"
        }
      }
    }
  EOF
  force_destroy                  = true
  depends_on                     = [time_sleep.kb_oss_collection_sleep]
}

#AWS Account ID
output "cloudgoat_output_aws_account_id" {
  value = data.aws_caller_identity.aws-account-id.account_id
}
output "scenario_cg_id" {
  value = var.cgid
}

#IAM User Credentials
output "access_key_id" {
  value = aws_iam_access_key.starting_user_key.id
}
output "secret_access_key" {
  value     = aws_iam_access_key.starting_user_key.secret
  sensitive = true
}

## This is used for the CloudGoat scenario to pull the AWS profile from the CloudGoat configuration.
## Configure required Terraform and provider versions.

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.74.0"
    }
    opensearch = {
      source  = "opensearch-project/opensearch"
      version = "= 2.2.0"
    }
    time = {
      source  = "hashicorp/time"
      version = ">= 0.9"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  # This configures default tags for all resources
  default_tags {
    tags = {
      Name     = "cg-${var.cgid}"
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

# Bucket the KnowledgeBase is trained on
resource "aws_s3_bucket" "kb_s3_bucket" {
  bucket = "cg-knowldegebase-bucket-${replace(var.cgid, "/[^a-z0-9-.]/", "-")}"
}

resource "aws_s3_object" "example_file" {
  bucket       = aws_s3_bucket.kb_s3_bucket.bucket
  key          = "flag.txt"
  content      = "FLAG{ar3_y0u_@n_ag3nt?}"
  content_type = "text/plain"
}

# Bucket the CodeInterpreter role has access to
resource "aws_s3_bucket" "kb_code_interpreter_bucket" {
  bucket = "cg-codeinterpreter-artifacts-${replace(var.cgid, "/[^a-z0-9-.]/", "-")}"
}

resource "aws_s3_object" "decoy_file" {
  bucket       = aws_s3_bucket.kb_code_interpreter_bucket.bucket
  key          = "flag.txt"
  content      = "Your flag is in another location..."
  content_type = "text/plain"
}

variable "profile" {
  description = "The AWS profile to use"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming"
  type        = string
}

variable "cg_whitelist" {
  description = "User's public IP address(es)"
  type        = list(string)
}

variable "region" {
  description = "The AWS region to deploy to"
  default     = "us-east-1"
  type        = string
}

variable "stack-name" {
  description = "Name of the CloudGoat stack"
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario"
  default     = "agentcore_identity_confusion"
  type        = string
}

# Scenario Specific Variables
variable "kb_model_id" {
  description = "The ID of the foundational model used by the knowledge base."
  type        = string
  default     = "amazon.titan-embed-text-v2:0"
}
